'use strict';
const $=s=>document.querySelector(s);
const scenes={
record:{title:'直接找到，<br>那条你关心的记录。',description:'询问文档中的末条有效记录，让大圆整理字段、状态和定位信息。',command:"dayuan ask '查询问题清单末条记录'",heading:'项目问题清单',body:'<div class="table-row table-head"><span>字段</span><span>内容</span></div><div class="table-row"><span>记录</span><span>末条有效记录</span></div><div class="table-row"><span>描述</span><span>附件数量限制未生效</span></div><div class="table-row"><span>状态</span><span><i class="status-dot"></i> 待解决</span></div><div class="table-row"><span>附件</span><span>1 张图片</span></div>'},
image:{title:'附件里的细节，<br>也在回答里。',description:'让大圆读取附件图片，结合画面文字，概括问题与上下文。',command:"dayuan ask '读取这条记录的图片附件并概括问题'",heading:'附件图片理解',body:'<div class="demo-image-result"><span class="mini-label">示例识别结果</span><strong>已选择 11 个文件，<br>界面提示最多上传 10 个。</strong>截图中的可见文字与记录描述相互补充，帮助定位问题。<div class="alert">可见提示：文件数量超过上限</div></div>'},
table:{title:'完整的结构，<br>留给下一步使用。',description:'返回 Markdown 与表格内容。复制、保存，或继续交给下一个工具处理。',command:"dayuan ask '按表格整理记录字段' --output result.txt",heading:'Markdown 结构化结果',body:'<div class="table-row table-head"><span>字段</span><span>内容</span></div><div class="table-row"><span>序号</span><span>21（示例）</span></div><div class="table-row"><span>状态</span><span>待解决</span></div><div class="table-row"><span>备注</span><span>空</span></div><div class="table-row"><span>输出</span><span>result.txt · Markdown</span></div>'}}
let demoTimer=null;
function activateTabs(group,active){document.querySelectorAll(group).forEach(el=>{const selected=el===active;el.setAttribute('aria-selected',String(selected));el.tabIndex=selected?0:-1;});}
function setScene(button){if(demoTimer)clearTimeout(demoTimer);$('#play-demo').disabled=false;$('#play-demo').lastElementChild.textContent='播放演示';$('.demo-result').classList.remove('playing');document.querySelectorAll('[data-phase]').forEach(x=>x.classList.remove('active'));activateTabs('[data-scene]',button);const scene=scenes[button.dataset.scene];$('#demo-title').innerHTML=scene.title;$('#demo-description').textContent=scene.description;$('#demo-command').textContent=scene.command;$('#demo-result-title').textContent=scene.heading;$('#demo-result-body').innerHTML=scene.body;$('#demo-content').setAttribute('aria-labelledby',button.id);$('#demo-badge').textContent='示例结果';}
document.querySelectorAll('[data-scene]').forEach(button=>button.addEventListener('click',()=>setScene(button)));
$('#play-demo').addEventListener('click',()=>{const button=$('#play-demo');button.disabled=true;button.lastElementChild.textContent='演示进行中';$('#demo-badge').textContent='正在处理';$('.demo-result').classList.add('playing');let phase=0;const advance=()=>{document.querySelectorAll('[data-phase]').forEach((el,index)=>el.classList.toggle('active',index<=phase));if(phase<2){phase++;demoTimer=setTimeout(advance,550);}else{$('.demo-result').classList.remove('playing');$('#demo-badge').textContent='示例已完成';button.disabled=false;button.lastElementChild.textContent='再次演示';$('#demo-announcement').textContent='示例演示完成。此过程未提交真实任务。';}};advance();});
const steps={install:{kicker:'标准 macOS 安装包',title:'双击安装，<br>后台服务随即就绪。',copy:'下载并打开安装包，按系统提示完成管理员授权。安装程序会注册 launchd 后台服务。',command:'dayuan status',note:'服务版不再需要每 30 分钟重新授权。仅本机预览构建，安装后仍需在目标 Mac 验收。',tag:'DayuanBridge.pkg'},prepare:{kicker:'使用已有企微登录',title:'企微保持登录，<br>后台自动就绪。',copy:'保持企微登录，圆桥自动准备后台控制器，无需打开大圆窗口或选择历史对话。无需已有大圆历史，首次调用自动创建专用会话。',command:'dayuan status',note:'后台控制器独立于前台助理窗口。账号没有的文档权限，圆桥也不会增加。',tag:'Signed-in WeCom'},use:{kicker:'通过 CLI 调用',title:'告诉它你的问题，<br>继续手头的工作。',copy:'在终端提交自然语言查询，或让 AI 助手直接执行 dayuan 命令。',command:"dayuan ask '查询项目问题清单末条记录及附件图片'",note:'保留任务 ID，使用 dayuan result 读取结果。',tag:'CLI'}};
document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{activateTabs('[data-step]',button);const step=steps[button.dataset.step];$('#setup-detail').setAttribute('aria-labelledby',button.id);$('#setup-kicker').textContent=step.kicker;$('#setup-title').innerHTML=step.title;$('#setup-copy').textContent=step.copy;$('#setup-command').textContent=step.command;$('#setup-note').textContent=step.note;$('.package-tag').textContent=step.tag;}));
let toastTimer;function toast(text){const node=$('#toast');node.textContent=text;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),1800);}
async function copy(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);}else{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();const ok=document.execCommand('copy');input.remove();if(!ok)throw new Error('copy');}toast('已复制，可直接粘贴到终端');}catch(e){toast('未能复制，请选择命令文字后手动复制');}}
document.querySelectorAll('[data-copy-target]').forEach(button=>button.addEventListener('click',()=>copy(document.getElementById(button.dataset.copyTarget).textContent)));
for(const group of ['[data-scene]','[data-step]','[data-usage]']){const buttons=[...document.querySelectorAll(group)];buttons.forEach((button,index)=>button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'||event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].click();}));}
